276	fn alpha_mul(color: u32, scale: u32) -> u32 {
277	    let mask = 0xff00ff;
278	    let rb = ((color & mask) * scale) >> 8;
279	    let ag = ((color >> 8) & mask) * scale;
280	    (rb & mask) | (ag & !mask)
