1	//! Utilities for color font handling
2	
3	use std::io::Read;
4	
5	use ttf_parser::{GlyphId, RgbaColor};
6	use typst_syntax::Span;
7	use usvg::tiny_skia_path;
8	use xmlwriter::XmlWriter;
9	
10	use crate::foundations::Bytes;
11	use crate::layout::{Abs, Frame, FrameItem, Point, Rect, Size};
12	use crate::text::FontInstance;
13	use crate::visualize::{
14	    ExchangeFormat, FixedStroke, Geometry, Image, RasterImage, Shape, SvgImage,
15	};
