17	/// Whether this glyph should be rendered via simple outlining instead of via
18	/// `glyph_frame`.
19	pub fn should_outline(font: &FontInstance, glyph_id: GlyphId) -> bool {
20	    let ttf = font.ttf();
21	    (ttf.tables().glyf.is_some()
22	        || ttf.tables().cff.is_some()
23	        || ttf.tables().cff2.is_some())
24	        && !ttf
25	            .glyph_raster_image(glyph_id, u16::MAX)
26	            .is_some_and(|img| img.format == ttf_parser::RasterImageFormat::PNG)
27	        && !ttf.is_color_glyph(glyph_id)
28	        && ttf.glyph_svg_image(glyph_id).is_none()
29	}
30	
31	/// A frame that can draw a glyph.
32	#[derive(Clone)]
33	pub struct GlyphFrame {
34	    pub upem: Abs,
35	    pub item: GlyphFrameItem,
36	}
37	
38	impl GlyphFrame {
39	    /// The font unit square.
40	    pub fn size(&self) -> Size {
41	        Size::splat(self.upem)
42	    }
43	}
44	
45	impl From<GlyphFrame> for Frame {
46	    fn from(g: GlyphFrame) -> Self {
47	        let mut frame = Frame::soft(Size::splat(g.upem));
48	        match g.item {
49	            GlyphFrameItem::Tofu(pos, shape) => {
50	                frame.push(pos, FrameItem::Shape(shape, Span::detached()));
51	            }
52	            GlyphFrameItem::Image(pos, image, size) => {
53	                frame.push(pos, FrameItem::Image(image, size, Span::detached()));
54	            }
55	        }
56	        frame
57	    }
58	}
59	
60	/// The glyph item that is drawn.
61	#[derive(Clone)]
62	pub enum GlyphFrameItem {
63	    /// A fallback rectangle.
64	    Tofu(Point, Shape),
65	    /// An image glyph.
66	    Image(Point, Image, Size),
67	}
68	
69	impl GlyphFrameItem {
70	    /// The position of the glyph item inside the parent frame.
71	    pub fn pos(&self) -> Point {
72	        match *self {
73	            GlyphFrameItem::Tofu(pos, _) => pos,
74	            GlyphFrameItem::Image(pos, _, _) => pos,
75	        }
76	    }
77	}
78	
79	/// Returns a frame representing a glyph and whether it is a fallback tofu
80	/// frame.
81	///
82	/// Should only be called on glyphs for which [`should_outline`] returns false.
83	///
84	/// The glyphs are sized in font units, [`text.item.size`] is not taken into
85	/// account.
86	///
87	/// [`text.item.size`]: crate::text::TextItem::size
88	#[comemo::memoize]
89	pub fn glyph_frame(font: &FontInstance, glyph_id: u16) -> Option<GlyphFrame> {
90	    let upem = Abs::pt(font.units_per_em());
91	    let glyph_id = GlyphId(glyph_id);
92	
93	    if let Some(frame) = draw_glyph(font, upem, glyph_id) {
94	        return Some(frame);
95	    }
96	
97	    // Generate a fallback tofu if the glyph couldn't be drawn, unless it is
98	    // the space glyph. Then, an empty frame does the job. (This happens for
99	    // some rare CBDT fonts, which don't define a bitmap for the space, but
100	    // also don't have a glyf or CFF table.)
101	    let not_space = font.ttf().glyph_index(' ') != Some(glyph_id);
102	    not_space.then(|| draw_fallback_tofu(font, upem, glyph_id))
103	}
104	
105	/// Tries to draw a glyph.
106	fn draw_glyph(font: &FontInstance, upem: Abs, glyph_id: GlyphId) -> Option<GlyphFrame> {
107	    let ttf = font.ttf();
108	    let kind = if let Some(raster_image) = ttf
109	        .glyph_raster_image(glyph_id, u16::MAX)
110	        .filter(|img| img.format == ttf_parser::RasterImageFormat::PNG)
111	    {
112	        draw_raster_glyph(font, upem, raster_image)
113	    } else if ttf.is_color_glyph(glyph_id) {
114	        draw_colr_glyph(font, glyph_id)
115	    } else if ttf.glyph_svg_image(glyph_id).is_some() {
116	        draw_svg_glyph(font, glyph_id)
117	    } else {
118	        None
119	    };
120	
121	    kind.map(|kind| GlyphFrame { upem, item: kind })
122	}
