124	/// Draws a fallback tofu box with the advance width of the glyph.
125	fn draw_fallback_tofu(font: &FontInstance, upem: Abs, glyph_id: GlyphId) -> GlyphFrame {
126	    let advance = font
127	        .ttf()
128	        .glyph_hor_advance(glyph_id)
129	        .map(|advance| Abs::pt(advance as f64))
130	        .unwrap_or(upem / 3.0);
131	    let inset = 0.15 * advance;
132	    let height = 0.7 * upem;
133	    let pos = Point::new(inset, upem - height);
134	    let size = Size::new(advance - inset * 2.0, height);
135	    let thickness = upem / 20.0;
136	    let stroke = FixedStroke { thickness, ..Default::default() };
137	    let shape = Geometry::Rect(size).stroked(stroke);
138	    GlyphFrame { upem, item: GlyphFrameItem::Tofu(pos, shape) }
139	}
