141	/// Draws a raster glyph in a frame.
142	///
143	/// Supports only PNG images.
144	fn draw_raster_glyph(
145	    font: &FontInstance,
146	    upem: Abs,
147	    raster_image: ttf_parser::RasterGlyphImage,
148	) -> Option<GlyphFrameItem> {
149	    let data = Bytes::new(raster_image.data.to_vec());
150	    let image = Image::plain(RasterImage::plain(data, ExchangeFormat::Png).ok()?);
151	
152	    let scale = upem / raster_image.pixels_per_em as f64;
153	    let image_width = scale * image.width();
154	    let image_height = scale * image.height();
155	
156	    let x_offset = scale * raster_image.x as f64;
157	    let mut y_offset = scale * raster_image.y as f64;
158	    // Apple Color emoji doesn't provide offset information (or at least
159	    // not in a way ttf-parser understands), so we artificially shift their
160	    // baseline to make it look good.
161	    if font.info().family.to_lowercase() == "apple color emoji" {
162	        // This factor is just taken from krilla.
163	        y_offset -= 0.128 * upem;
164	    }
165	
166	    let position = Point::new(-x_offset, -(image_height + y_offset));
167	    let size = Size::new(image_width, image_height);
168	    Some(GlyphFrameItem::Image(position, image, size))
169	}
