171	/// Draws a glyph from the COLR table into the frame.
172	fn draw_colr_glyph(font: &FontInstance, glyph_id: GlyphId) -> Option<GlyphFrameItem> {
173	    let svg_string = colr_glyph_to_svg(font, glyph_id)?;
174	
175	    let ttf = font.ttf();
176	    let width = ttf.global_bounding_box().width() as f64;
177	    let height = ttf.global_bounding_box().height() as f64;
178	    let x_min = ttf.global_bounding_box().x_min as f64;
179	    let y_max = ttf.global_bounding_box().y_max as f64;
180	
181	    let data = Bytes::from_string(svg_string);
182	    let image = Image::plain(SvgImage::new(data).ok()?);
183	
184	    let position = Point::new(Abs::pt(x_min), Abs::pt(-y_max));
185	    let size = Size::new(Abs::pt(width), Abs::pt(height));
186	    Some(GlyphFrameItem::Image(position, image, size))
187	}
