189	/// Convert a COLR glyph into an SVG file.
190	fn colr_glyph_to_svg(font: &FontInstance, glyph_id: GlyphId) -> Option<String> {
191	    let mut svg = XmlWriter::new(xmlwriter::Options::default());
192	
193	    let ttf = font.ttf();
194	    let width = ttf.global_bounding_box().width() as f64;
195	    let height = ttf.global_bounding_box().height() as f64;
196	    let x_min = ttf.global_bounding_box().x_min as f64;
197	    let y_max = ttf.global_bounding_box().y_max as f64;
198	    let tx = -x_min;
199	    let ty = -y_max;
200	
201	    svg.start_element("svg");
202	    svg.write_attribute("xmlns", "http://www.w3.org/2000/svg");
203	    svg.write_attribute("xmlns:xlink", "http://www.w3.org/1999/xlink");
204	    svg.write_attribute("width", &width);
205	    svg.write_attribute("height", &height);
206	    svg.write_attribute_fmt("viewBox", format_args!("0 0 {width} {height}"));
207	
208	    let mut path_buf = String::with_capacity(256);
209	    let gradient_index = 1;
210	    let clip_path_index = 1;
211	
212	    svg.start_element("g");
213	    svg.write_attribute_fmt(
214	        "transform",
215	        format_args!("matrix(1 0 0 -1 0 0) matrix(1 0 0 1 {tx} {ty})"),
216	    );
217	
218	    let mut glyph_painter = GlyphPainter {
219	        face: ttf,
220	        svg: &mut svg,
221	        path_buf: &mut path_buf,
222	        gradient_index,
223	        clip_path_index,
224	        palette_index: 0,
225	        transform: ttf_parser::Transform::default(),
226	        outline_transform: ttf_parser::Transform::default(),
227	        transforms_stack: vec![ttf_parser::Transform::default()],
228	    };
229	
230	    ttf.paint_color_glyph(glyph_id, 0, RgbaColor::new(0, 0, 0, 255), &mut glyph_painter)?;
231	    svg.end_element();
232	
233	    Some(svg.end_document())
234	}
