236	/// Draws an SVG glyph in a frame.
237	fn draw_svg_glyph(font: &FontInstance, glyph_id: GlyphId) -> Option<GlyphFrameItem> {
238	    // TODO: Our current conversion of the SVG table works for Twitter Color Emoji,
239	    // but might not work for others. See also: https://github.com/RazrFalcon/resvg/pull/776
240	    let mut data = font.ttf().glyph_svg_image(glyph_id)?.data;
241	
242	    // Decompress SVGZ.
243	    let mut decoded = vec![];
244	    if data.starts_with(&[0x1f, 0x8b]) {
245	        let mut decoder = flate2::read::GzDecoder::new(data);
246	        decoder.read_to_end(&mut decoded).ok()?;
247	        data = &decoded;
248	    }
249	
250	    // Parse and simplify the SVG.
251	    let xml = std::str::from_utf8(data).ok()?;
252	    let document = roxmltree::Document::parse(xml).ok()?;
253	    let opts = usvg::Options::default();
254	    let tree = usvg::Tree::from_xmltree(&document, &opts).ok()?;
255	    let mut data = tree.to_string(&usvg::WriteOptions {
256	        indent: usvg::Indent::None,
257	        attributes_indent: usvg::Indent::None,
258	        ..Default::default()
259	    });
260	
261	    // The SVG coordinates and the font coordinates are not the same: the Y axis
262	    // is mirrored. But the origin of the axes are the same (which means that
263	    // the horizontal axis in the SVG document corresponds to the baseline). See
264	    // the reference for more details:
265	    // https://learn.microsoft.com/en-us/typography/opentype/spec/svg#coordinate-systems-and-glyph-metrics
266	    //
267	    // Using this SVG directly can result in a cropped glyph. In order to avoid
268	    // clipping issues, we apply a translate transform so the top-left corner of
269	    // the bounding box is moved into the origin (0, 0) to make it fully fit
270	    // into the view port defined by `viewBox="0 0 width height"`, like a
271	    // conventional SVG.
272	    let bbox = tree.root().bounding_box();
273	    let view_box = Rect::new(
274	        Point::new(Abs::pt(bbox.left() as f64), Abs::pt(bbox.top() as f64)),
275	        Point::new(Abs::pt(bbox.right() as f64), Abs::pt(bbox.bottom() as f64)),
276	    );
277	    fixup_svg(&mut data, view_box);
278	
279	    let data = Bytes::from_string(data);
280	    let image = Image::plain(SvgImage::new(data).ok()?);
281	
282	    let position = Point::new(view_box.min.x, view_box.min.y);
283	    let size = view_box.size();
284	    Some(GlyphFrameItem::Image(position, image, size))
285	}
