287	/// Replace or insert the size attributes (viewBox, width and height), and
288	/// insert a group with a transform that translates the `viewBox` so that the
289	/// top-left point is at the origin (0, 0).
290	fn fixup_svg(svg: &mut String, view_box: Rect) {
291	    let mut viewbox_range = None;
292	    let mut width_range = None;
293	    let mut height_range = None;
294	
295	    let mut s = unscanny::Scanner::new(svg);
296	    s.eat_until("<svg");
297	    s.expect("<svg");
298	
299	    let svg_attr_start = s.cursor();
300	
301	    while !s.eat_if('>') && !s.done() {
302	        s.eat_whitespace();
303	        let start = s.cursor();
304	
305	        let attr_name = s.eat_until('=').trim();
306	        // Eat the equal sign and the quote.
307	        s.expect('=');
308	        s.eat_until('"');
309	        s.expect('"');
310	
311	        while !s.eat_if('"') && !s.done() {
312	            s.eat();
313	        }
314	
315	        match attr_name {
316	            "viewBox" => viewbox_range = Some(start..s.cursor()),
317	            "width" => width_range = Some(start..s.cursor()),
318	            "height" => height_range = Some(start..s.cursor()),
319	            _ => {}
320	        }
321	    }
322	
323	    let svg_body_start = s.cursor();
324	    let Some(svg_body_end) = svg.rfind("</svg>") else {
325	        return;
326	    };
327	
328	    svg.insert_str(svg_body_end, "</g>");
329	    svg.insert_str(
330	        svg_body_start,
331	        &format!(
332	            r#"<g transform="translate({} {})">"#,
333	            -view_box.min.x.to_pt(),
334	            -view_box.min.y.to_pt()
335	        ),
336	    );
337	
338	    let size = view_box.size();
339	    let mut edits = [
340	        (
341	            viewbox_range,
342	            format!("viewBox=\"0 0 {} {}\"", size.x.to_pt(), size.y.to_pt(),),
343	        ),
344	        (width_range, format!("width=\"{}\"", size.x.to_pt())),
345	        (height_range, format!("height=\"{}\"", size.y.to_pt())),
346	    ];
347	
348	    // Sort edits by ranges; missing ranges will be moved to the start.
349	    edits.sort_by_key(|(range, _)| range.clone().map(|r| r.start));
350	
351	    // Replace or insert the attribute. Iterate in reverse, so the modifying the
352	    // string doesn't affect the ranges of the edits that are applied later on.
353	    for (range, str) in edits.into_iter().rev() {
354	        if let Some(range) = range {
355	            svg.replace_range(range, &str);
356	        } else {
357	            svg.insert_str(svg_attr_start, &str);
358	            svg.insert(svg_attr_start, ' ');
359	        }
360	    }
361	}
