399	// NOTE: This is only a best-effort translation of COLR into SVG. It's not feature-complete
400	// and it's also not possible to make it feature-complete using just raw SVG features.
401	pub(crate) struct GlyphPainter<'a> {
402	    pub(crate) face: &'a ttf_parser::Face<'a>,
403	    pub(crate) svg: &'a mut xmlwriter::XmlWriter,
404	    pub(crate) path_buf: &'a mut String,
405	    pub(crate) gradient_index: usize,
406	    pub(crate) clip_path_index: usize,
407	    pub(crate) palette_index: u16,
408	    pub(crate) transform: ttf_parser::Transform,
409	    pub(crate) outline_transform: ttf_parser::Transform,
410	    pub(crate) transforms_stack: Vec<ttf_parser::Transform>,
411	}
412	
413	impl<'a> GlyphPainter<'a> {
414	    fn write_gradient_stops(&mut self, stops: ttf_parser::colr::GradientStopsIter) {
415	        for stop in stops {
416	            self.svg.start_element("stop");
417	            self.svg.write_attribute("offset", &stop.stop_offset);
418	            self.write_color_attribute("stop-color", stop.color);
419	            let opacity = f32::from(stop.color.alpha) / 255.0;
420	            self.svg.write_attribute("stop-opacity", &opacity);
421	            self.svg.end_element();
422	        }
423	    }
424	
425	    fn write_color_attribute(&mut self, name: &str, color: ttf_parser::RgbaColor) {
426	        self.svg.write_attribute_fmt(
427	            name,
428	            format_args!("rgb({}, {}, {})", color.red, color.green, color.blue),
429	        );
430	    }
431	
432	    fn write_transform_attribute(&mut self, name: &str, ts: ttf_parser::Transform) {
433	        if ts.is_default() {
434	            return;
435	        }
436	
437	        self.svg.write_attribute_fmt(
438	            name,
439	            format_args!("matrix({} {} {} {} {} {})", ts.a, ts.b, ts.c, ts.d, ts.e, ts.f),
440	        );
441	    }
442	
443	    fn write_spread_method_attribute(
444	        &mut self,
445	        extend: ttf_parser::colr::GradientExtend,
446	    ) {
447	        self.svg.write_attribute(
448	            "spreadMethod",
449	            match extend {
450	                ttf_parser::colr::GradientExtend::Pad => &"pad",
451	                ttf_parser::colr::GradientExtend::Repeat => &"repeat",
452	                ttf_parser::colr::GradientExtend::Reflect => &"reflect",
453	            },
454	        );
455	    }
456	
457	    fn paint_solid(&mut self, color: ttf_parser::RgbaColor) {
458	        self.svg.start_element("path");
459	        self.write_color_attribute("fill", color);
460	        let opacity = f32::from(color.alpha) / 255.0;
461	        self.svg.write_attribute("fill-opacity", &opacity);
462	        self.write_transform_attribute("transform", self.outline_transform);
463	        self.svg.write_attribute("d", self.path_buf);
464	        self.svg.end_element();
465	    }
466	
467	    fn paint_linear_gradient(&mut self, gradient: ttf_parser::colr::LinearGradient<'a>) {
468	        let gradient_id = format!("lg{}", self.gradient_index);
469	        self.gradient_index += 1;
470	
471	        let gradient_transform = paint_transform(self.outline_transform, self.transform);
472	
473	        // TODO: We ignore x2, y2. Have to apply them somehow.
474	        // TODO: The way spreadMode works in ttf and svg is a bit different. In SVG, the spreadMode
475	        // will always be applied based on x1/y1 and x2/y2. However, in TTF the spreadMode will
476	        // be applied from the first/last stop. So if we have a gradient with x1=0 x2=1, and
477	        // a stop at x=0.4 and x=0.6, then in SVG we will always see a padding, while in ttf
478	        // we will see the actual spreadMode. We need to account for that somehow.
479	        self.svg.start_element("linearGradient");
480	        self.svg.write_attribute("id", &gradient_id);
481	        self.svg.write_attribute("x1", &gradient.x0);
482	        self.svg.write_attribute("y1", &gradient.y0);
483	        self.svg.write_attribute("x2", &gradient.x1);
484	        self.svg.write_attribute("y2", &gradient.y1);
485	        self.svg.write_attribute("gradientUnits", &"userSpaceOnUse");
486	        self.write_spread_method_attribute(gradient.extend);
487	        self.write_transform_attribute("gradientTransform", gradient_transform);
488	        self.write_gradient_stops(
489	            gradient.stops(self.palette_index, self.face.variation_coordinates()),
490	        );
491	        self.svg.end_element();
492	
493	        self.svg.start_element("path");
494	        self.svg
495	            .write_attribute_fmt("fill", format_args!("url(#{gradient_id})"));
496	        self.write_transform_attribute("transform", self.outline_transform);
497	        self.svg.write_attribute("d", self.path_buf);
498	        self.svg.end_element();
499	    }
500	
501	    fn paint_radial_gradient(&mut self, gradient: ttf_parser::colr::RadialGradient<'a>) {
502	        let gradient_id = format!("rg{}", self.gradient_index);
503	        self.gradient_index += 1;
504	
505	        let gradient_transform = paint_transform(self.outline_transform, self.transform);
506	
507	        self.svg.start_element("radialGradient");
508	        self.svg.write_attribute("id", &gradient_id);
509	        self.svg.write_attribute("cx", &gradient.x1);
510	        self.svg.write_attribute("cy", &gradient.y1);
511	        self.svg.write_attribute("r", &gradient.r1);
512	        self.svg.write_attribute("fr", &gradient.r0);
513	        self.svg.write_attribute("fx", &gradient.x0);
514	        self.svg.write_attribute("fy", &gradient.y0);
515	        self.svg.write_attribute("gradientUnits", &"userSpaceOnUse");
516	        self.write_spread_method_attribute(gradient.extend);
517	        self.write_transform_attribute("gradientTransform", gradient_transform);
518	        self.write_gradient_stops(
519	            gradient.stops(self.palette_index, self.face.variation_coordinates()),
520	        );
521	        self.svg.end_element();
522	
523	        self.svg.start_element("path");
524	        self.svg
525	            .write_attribute_fmt("fill", format_args!("url(#{gradient_id})"));
526	        self.write_transform_attribute("transform", self.outline_transform);
527	        self.svg.write_attribute("d", self.path_buf);
528	        self.svg.end_element();
529	    }
