534	fn paint_transform(
535	    outline_transform: ttf_parser::Transform,
536	    transform: ttf_parser::Transform,
537	) -> ttf_parser::Transform {
538	    let outline_transform = tiny_skia_path::Transform::from_row(
539	        outline_transform.a,
540	        outline_transform.b,
541	        outline_transform.c,
542	        outline_transform.d,
543	        outline_transform.e,
544	        outline_transform.f,
545	    );
546	
547	    let gradient_transform = tiny_skia_path::Transform::from_row(
548	        transform.a,
549	        transform.b,
550	        transform.c,
551	        transform.d,
552	        transform.e,
553	        transform.f,
554	    );
555	
556	    let gradient_transform = outline_transform
557	        .invert()
558	        // In theory, we should error out. But the transform shouldn't ever be uninvertible, so let's ignore it.
559	        .unwrap_or_default()
560	        .pre_concat(gradient_transform);
561	
562	    ttf_parser::Transform {
563	        a: gradient_transform.sx,
564	        b: gradient_transform.ky,
565	        c: gradient_transform.kx,
566	        d: gradient_transform.sy,
567	        e: gradient_transform.tx,
568	        f: gradient_transform.ty,
569	    }
570	}
