572	impl GlyphPainter<'_> {
573	    fn clip_with_path(&mut self, path: &str) {
574	        let clip_id = format!("cp{}", self.clip_path_index);
575	        self.clip_path_index += 1;
576	
577	        self.svg.start_element("clipPath");
578	        self.svg.write_attribute("id", &clip_id);
579	        self.svg.start_element("path");
580	        self.write_transform_attribute("transform", self.outline_transform);
581	        self.svg.write_attribute("d", &path);
582	        self.svg.end_element();
583	        self.svg.end_element();
584	
585	        self.svg.start_element("g");
586	        self.svg
587	            .write_attribute_fmt("clip-path", format_args!("url(#{clip_id})"));
588	    }
