591	impl<'a> ttf_parser::colr::Painter<'a> for GlyphPainter<'a> {
592	    fn outline_glyph(&mut self, glyph_id: ttf_parser::GlyphId) {
593	        self.path_buf.clear();
594	        let mut builder = ColrBuilder(self.path_buf);
595	        match self.face.outline_glyph(glyph_id, &mut builder) {
596	            Some(v) => v,
597	            None => return,
598	        };
599	        builder.finish();
600	
601	        // We have to write outline using the current transform.
602	        self.outline_transform = self.transform;
603	    }
604	
605	    fn push_layer(&mut self, mode: ttf_parser::colr::CompositeMode) {
606	        self.svg.start_element("g");
607	
608	        use ttf_parser::colr::CompositeMode;
609	        // TODO: Need to figure out how to represent the other blend modes
610	        // in SVG.
611	        let mode = match mode {
612	            CompositeMode::SourceOver => "normal",
613	            CompositeMode::Screen => "screen",
614	            CompositeMode::Overlay => "overlay",
615	            CompositeMode::Darken => "darken",
616	            CompositeMode::Lighten => "lighten",
617	            CompositeMode::ColorDodge => "color-dodge",
618	            CompositeMode::ColorBurn => "color-burn",
619	            CompositeMode::HardLight => "hard-light",
620	            CompositeMode::SoftLight => "soft-light",
621	            CompositeMode::Difference => "difference",
622	            CompositeMode::Exclusion => "exclusion",
623	            CompositeMode::Multiply => "multiply",
624	            CompositeMode::Hue => "hue",
625	            CompositeMode::Saturation => "saturation",
626	            CompositeMode::Color => "color",
627	            CompositeMode::Luminosity => "luminosity",
628	            _ => "normal",
629	        };
630	        self.svg.write_attribute_fmt(
631	            "style",
632	            format_args!("mix-blend-mode: {mode}; isolation: isolate"),
633	        );
634	    }
635	
636	    fn pop_layer(&mut self) {
637	        self.svg.end_element(); // g
638	    }
639	
640	    fn push_transform(&mut self, transform: ttf_parser::Transform) {
641	        self.transforms_stack.push(self.transform);
642	        self.transform = ttf_parser::Transform::combine(self.transform, transform);
643	    }
644	
645	    fn paint(&mut self, paint: ttf_parser::colr::Paint<'a>) {
646	        match paint {
647	            ttf_parser::colr::Paint::Solid(color) => self.paint_solid(color),
648	            ttf_parser::colr::Paint::LinearGradient(lg) => self.paint_linear_gradient(lg),
649	            ttf_parser::colr::Paint::RadialGradient(rg) => self.paint_radial_gradient(rg),
650	            ttf_parser::colr::Paint::SweepGradient(sg) => self.paint_sweep_gradient(sg),
651	        }
652	    }
653	
654	    fn pop_transform(&mut self) {
655	        if let Some(ts) = self.transforms_stack.pop() {
656	            self.transform = ts;
657	        }
658	    }
659	
660	    fn push_clip(&mut self) {
661	        self.clip_with_path(&self.path_buf.clone());
662	    }
663	
664	    fn pop_clip(&mut self) {
665	        self.svg.end_element();
666	    }
667	
668	    fn push_clip_box(&mut self, clipbox: ttf_parser::colr::ClipBox) {
669	        let x_min = clipbox.x_min;
670	        let x_max = clipbox.x_max;
671	        let y_min = clipbox.y_min;
672	        let y_max = clipbox.y_max;
673	
674	        let clip_path = format!(
675	            "M {x_min} {y_min} L {x_max} {y_min} L {x_max} {y_max} L {x_min} {y_max} Z"
676	        );
677	
678	        self.clip_with_path(&clip_path);
679	    }
680	}
